-- ============================================
-- LUMA — Thème 10 : MOYEN 3/3 x4 — Confronter un suspect avec des preuves
-- ============================================


update scenarios set content = '{"characters": {"suspect": "le suspect", "partner": "votre collègue"}, "start_node": "n1", "nodes": {"n1": {"speaker": "suspect", "text": "I''ve told you everything already. I don''t know why I''m still here.", "text_fr": "Je vous ai déjà tout dit. Je sais pas pourquoi je suis encore là.", "choices": [{"text": "We have your fingerprints from the scene. Care to explain that?", "text_fr": "On a vos empreintes de la scène. Vous voulez expliquer ça ?", "next": "n2"}, {"text": "Your alibi doesn''t match the security footage we obtained.", "text_fr": "Votre alibi ne correspond pas aux images de sécurité qu''on a obtenues.", "next": "n2b"}]}, "n2": {"speaker": "suspect", "text": "(Pales slightly) That''s... that could be from a previous visit, I go there sometimes.", "text_fr": "(Pâlit légèrement) Ça... ça pourrait être d''une visite précédente, j''y vais parfois.", "choices": [{"text": "The prints were fresh, found on items moved during the break-in.", "text_fr": "Les empreintes étaient fraîches, trouvées sur des objets déplacés pendant le cambriolage.", "next": "n3"}]}, "n2b": {"speaker": "suspect", "text": "(Nervous laugh) Footage can be misleading, you know. Cameras get things wrong.", "text_fr": "(Rire nerveux) Les images peuvent être trompeuses, vous savez. Les caméras se trompent.", "choices": [{"text": "This footage clearly shows your car near the scene at the time of the break-in.", "text_fr": "Ces images montrent clairement votre voiture près de la scène au moment du cambriolage.", "next": "n3"}]}, "n3": {"speaker": "suspect", "text": "(Silence, avoiding eye contact) I... I might have been in the area, but I didn''t break in.", "text_fr": "(Silence, évite le contact visuel) J''ai... j''ai peut-être été dans le coin, mais j''ai pas cambriolé.", "choices": [{"text": "Then why lie about your alibi in the first place?", "text_fr": "Alors pourquoi mentir sur votre alibi en premier lieu ?", "next": "n4"}, {"text": "If you''re innocent, walk us through what actually happened that night.", "text_fr": "Si vous êtes innocent, expliquez-nous ce qui s''est vraiment passé cette nuit-là.", "next": "n4"}]}, "n4": {"speaker": "suspect", "text": "(Long pause, shoulders slumping) Fine. I was there, but not to steal anything.", "text_fr": "(Longue pause, épaules affaissées) Bon. J''étais là, mais pas pour voler quoi que ce soit.", "choices": [{"text": "Then what were you doing there?", "text_fr": "Alors qu''est-ce que vous faisiez là ?", "next": "n5"}]}, "n5": {"speaker": "suspect", "text": "I was meeting someone. Someone I shouldn''t have been meeting, if you understand.", "text_fr": "Je rencontrais quelqu''un. Quelqu''un que j''aurais pas dû rencontrer, si vous comprenez.", "choices": [{"text": "We need a name. This is a serious investigation.", "text_fr": "On a besoin d''un nom. C''est une enquête sérieuse.", "next": "n6"}, {"text": "Understood, but that still doesn''t explain the fingerprints on the moved items.", "text_fr": "Compris, mais ça n''explique toujours pas les empreintes sur les objets déplacés.", "next": "n6b"}]}, "n6": {"speaker": "suspect", "text": "(Hesitates) It was my business partner''s wife. We''ve been... involved. I panicked and touched things nervously.", "text_fr": "(Hésite) C''était la femme de mon associé. On a été... impliqués. J''ai paniqué et touché des choses nerveusement.", "choices": [{"text": "That''s a significant detail. We''ll need to verify this with her directly.", "text_fr": "C''est un détail significatif. On devra vérifier ça directement avec elle.", "next": "n7"}]}, "n6b": {"speaker": "suspect", "text": "(Sighs) I panicked when I heard a noise, and knocked some things over trying to hide.", "text_fr": "(Soupire) J''ai paniqué en entendant un bruit, et j''ai fait tomber des choses en essayant de me cacher.", "choices": [{"text": "That''s a plausible explanation, but we''ll need corroboration.", "text_fr": "C''est une explication plausible, mais on aura besoin de corroboration.", "next": "n7"}]}, "n7": {"speaker": "partner", "text": "(Steps in) If this checks out, it changes things significantly for this case.", "text_fr": "(Intervient) Si ça se confirme, ça change les choses considérablement pour cette affaire.", "choices": [{"text": "Agreed. Let''s follow up on this new lead immediately.", "text_fr": "D''accord. Suivons cette nouvelle piste immédiatement.", "next": "n8"}]}, "n8": {"speaker": "suspect", "text": "Please — my involvement with her, it can''t come out. It would destroy my business partnership.", "text_fr": "S''il vous plaît — mon implication avec elle, ça peut pas se savoir. Ça détruirait mon partenariat d''affaires.", "choices": [{"text": "We''ll handle this as discreetly as possible, but the truth matters most here.", "text_fr": "On va gérer ça aussi discrètement que possible, mais la vérité compte le plus ici.", "next": "end_confessed"}]}, "end_confessed": {"speaker": "partner", "text": "This confession, though messy, just cracked the case wide open.", "text_fr": "Cette confession, bien que compliquée, vient d''ouvrir l''affaire en grand.", "end": true, "ending_label": "Vérité révélée par la confrontation aux preuves 📋🔓"}}}'::jsonb, is_playable = true
where title = 'Confronter un suspect avec des preuves'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
